CREATE TABLE Users (UserId INT IDENTITY PRIMARY KEY, FullName NVARCHAR(120) NOT NULL, Username NVARCHAR(60) UNIQUE NOT NULL, Email NVARCHAR(180) UNIQUE NOT NULL, PasswordHash NVARCHAR(512) NOT NULL, Role NVARCHAR(30) NOT NULL, IsActive BIT NOT NULL CONSTRAINT DF_Users_IsActive DEFAULT 1, InvitationTokenHash NVARCHAR(64) NULL, InvitationExpiresAt DATETIME2 NULL);
CREATE TABLE Customers (CustomerId INT IDENTITY PRIMARY KEY, FullName NVARCHAR(120) NOT NULL, ContactNumber NVARCHAR(30), Email NVARCHAR(180), Address NVARCHAR(300), CustomerStatus NVARCHAR(30) NOT NULL DEFAULT 'Active', CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Devices (DeviceId INT IDENTITY PRIMARY KEY, CustomerId INT NOT NULL REFERENCES Customers(CustomerId), DeviceType NVARCHAR(60) NOT NULL, Brand NVARCHAR(60), Model NVARCHAR(80), SerialNumber NVARCHAR(120), OperatingSystem NVARCHAR(80), DeviceCondition NVARCHAR(40), Accessories NVARCHAR(300));
CREATE TABLE Technicians (TechnicianId INT IDENTITY PRIMARY KEY, FullName NVARCHAR(120) NOT NULL, ContactNumber NVARCHAR(30), Specialization NVARCHAR(120), Availability NVARCHAR(30) NOT NULL DEFAULT 'Available');
CREATE TABLE Suppliers (SupplierId INT IDENTITY PRIMARY KEY, CompanyName NVARCHAR(150) NOT NULL, Category NVARCHAR(80), ContactPerson NVARCHAR(120), ContactNumber NVARCHAR(30), Email NVARCHAR(180), Address NVARCHAR(300), PaymentTerms NVARCHAR(40), LeadTime NVARCHAR(40), IsActive BIT NOT NULL DEFAULT 1);
CREATE TABLE Parts (PartId INT IDENTITY PRIMARY KEY, PartName NVARCHAR(150) NOT NULL, Category NVARCHAR(80), Brand NVARCHAR(80), Description NVARCHAR(400), Quantity INT NOT NULL DEFAULT 0, ReorderLevel INT NOT NULL DEFAULT 5, UnitCost DECIMAL(12,2) NOT NULL, SellingPrice DECIMAL(12,2) NOT NULL, SupplierId INT REFERENCES Suppliers(SupplierId));
CREATE TABLE RepairJobs (RepairJobId INT IDENTITY PRIMARY KEY, CustomerId INT NOT NULL REFERENCES Customers(CustomerId), DeviceId INT NOT NULL REFERENCES Devices(DeviceId), TechnicianId INT REFERENCES Technicians(TechnicianId), Complaint NVARCHAR(500) NOT NULL, Diagnosis NVARCHAR(1000), RepairDescription NVARCHAR(1000), EstimatedCost DECIMAL(12,2), ActualCost DECIMAL(12,2), DateReceived DATE NOT NULL, ExpectedCompletionDate DATE, CompletionDate DATE, Priority NVARCHAR(20) NOT NULL DEFAULT 'Normal', RepairStatus NVARCHAR(30) NOT NULL DEFAULT 'Pending');
CREATE TABLE RepairParts (RepairJobId INT NOT NULL REFERENCES RepairJobs(RepairJobId), PartId INT NOT NULL REFERENCES Parts(PartId), Quantity INT NOT NULL, UnitPrice DECIMAL(12,2) NOT NULL, PRIMARY KEY (RepairJobId, PartId));
CREATE TABLE Invoices (InvoiceId INT IDENTITY PRIMARY KEY, RepairJobId INT NOT NULL REFERENCES RepairJobs(RepairJobId), LaborCost DECIMAL(12,2) NOT NULL DEFAULT 0, PartsCost DECIMAL(12,2) NOT NULL DEFAULT 0, OtherCharges DECIMAL(12,2) NOT NULL DEFAULT 0, Discount DECIMAL(12,2) NOT NULL DEFAULT 0, TotalAmount AS (LaborCost + PartsCost + OtherCharges - Discount), PaymentStatus NVARCHAR(30) NOT NULL DEFAULT 'Unpaid', InvoiceDate DATE NOT NULL DEFAULT GETDATE());
CREATE TABLE Payments (PaymentId INT IDENTITY PRIMARY KEY, InvoiceId INT NOT NULL REFERENCES Invoices(InvoiceId), Amount DECIMAL(12,2) NOT NULL, PaymentMethod NVARCHAR(30) NOT NULL, PaidAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE CustomerNotes (NoteId INT IDENTITY PRIMARY KEY, CustomerId INT NOT NULL REFERENCES Customers(CustomerId), NoteText NVARCHAR(1000) NOT NULL, CreatedBy INT REFERENCES Users(UserId), CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE RepairStatusHistory (HistoryId INT IDENTITY PRIMARY KEY, RepairJobId INT NOT NULL REFERENCES RepairJobs(RepairJobId), Status NVARCHAR(30) NOT NULL, ChangedBy INT REFERENCES Users(UserId), ChangedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), Note NVARCHAR(500));
CREATE TABLE Purchases (PurchaseId INT IDENTITY PRIMARY KEY, SupplierId INT NOT NULL REFERENCES Suppliers(SupplierId), PurchaseDate DATE NOT NULL, ReferenceNumber NVARCHAR(60), TotalAmount DECIMAL(12,2) NOT NULL DEFAULT 0);
CREATE TABLE PurchaseDetails (PurchaseId INT NOT NULL REFERENCES Purchases(PurchaseId), PartId INT NOT NULL REFERENCES Parts(PartId), Quantity INT NOT NULL, UnitCost DECIMAL(12,2) NOT NULL, PRIMARY KEY (PurchaseId, PartId));
